-- Warehouse Facility Audit Checklist — shared across Mayon, Consolacion,
-- and CDO warehouses, since their source Excel files are byte-identical
-- (confirmed by direct diff of every section/item/point value). QA-only
-- (requires_audit_type), point-weighted (1pt minor/5pt major), pass
-- threshold 92.5% per standing rule (source says 93%), Commitment Date
-- enabled (source has the same Nonconformities/Commitment Date fields as
-- Mayon Building's checklist).
--
-- FLAG: Section E (Delivery Vehicles) lists specific plate numbers (UCD
-- 426, WCT 769, etc.) as its items — these are almost certainly Mayon's
-- actual fleet, carried over unchanged into the Consolacion and CDO files
-- by copy-paste (Tarlac's own file, by contrast, has a completely
-- different, clearly location-specific plate list — NBV 3991, NIL 9587 —
-- proving each site's vehicles really do differ). Shipping this as one
-- shared template means Consolacion/CDO will show Mayon's plates until
-- someone corrects the item labels in this template via the admin Audit
-- Template editor (or asks for it to be split into 3 separate templates).
INSERT INTO public.audit_templates (
  id, title, description, sections, is_active, template_group, active_ticket,
  pass_threshold, requires_audit_type, requires_visit_number, requires_commitment_date,
  requires_department, has_time_restriction, available_from_time, available_to_time,
  store_restrictions, created_date, updated_date
)
SELECT
  gen_random_uuid()::text,
  'Warehouse Facility Audit Checklist',
  'Docking area, flour room, cold cuts area, main stockroom, and delivery vehicle condition check for warehouse facilities.',
  '[{"id":"whse_s1","title":"A. DOCKING AREA / LOBBY AREA","items":[{"id":"whse_s1_i1","label":"Area is free from insects and rodent infestation","photo_required":false,"pts":5},{"id":"whse_s1_i2","label":"Area is free from physical hazard","photo_required":false,"pts":5},{"id":"whse_s1_i3","label":"Newly delivered items are placed directly to Stockroom","photo_required":false,"pts":5},{"id":"whse_s1_i4","label":"No fresh meat stand by on receiving area at least 15 mins.","photo_required":false,"pts":5},{"id":"whse_s1_i5","label":"No item is placed directly on the floor","photo_required":false,"pts":5},{"id":"whse_s1_i6","label":"Floor - clean, dry, stain-free","photo_required":false,"pts":1},{"id":"whse_s1_i7","label":"Pallets - clean, good condition","photo_required":false,"pts":1},{"id":"whse_s1_i8","label":"Walls - clean, no stains, no scotch tape.","photo_required":false,"pts":1},{"id":"whse_s1_i9","label":"Instructional guides in proper places","photo_required":false,"pts":1},{"id":"whse_s1_i10","label":"Garage area - clean, well arranged, no stagnant water","photo_required":false,"pts":1},{"id":"whse_s1_i11","label":"Comfort room - clean, dry, stain-free and organized cleaning materials","photo_required":false,"pts":1},{"id":"whse_s1_i12","label":"Others","photo_required":false,"pts":1}]},{"id":"whse_s2","title":"B. FLOUR ROOM","items":[{"id":"whse_s2_i1","label":"Area is free from insects and rodent infestation","photo_required":false,"pts":5},{"id":"whse_s2_i2","label":"Area is free from physical hazard","photo_required":false,"pts":5},{"id":"whse_s2_i3","label":"No item is placed directly on the floor","photo_required":false,"pts":5},{"id":"whse_s2_i4","label":"Stocks in FIFO order","photo_required":false,"pts":5},{"id":"whse_s2_i5","label":"Floor - clean, dry, stain-free","photo_required":false,"pts":1},{"id":"whse_s2_i6","label":"Walls - clean, no shoe step marks, no stains, no scotch tape.","photo_required":false,"pts":1},{"id":"whse_s2_i7","label":"Ceiling - clean, free from cobwebs","photo_required":false,"pts":1},{"id":"whse_s2_i8","label":"Pallets - clean, good condition","photo_required":false,"pts":1},{"id":"whse_s2_i9","label":"Others","photo_required":false,"pts":1}]},{"id":"whse_s3","title":"C. COLD CUTS AREA","items":[{"id":"whse_s3_i1","label":"Area is free from insects and rodent infestation","photo_required":false,"pts":5},{"id":"whse_s3_i2","label":"Area is free from physical hazard","photo_required":false,"pts":5},{"id":"whse_s3_i3","label":"Cold cuts are in FIFO method, properly arranged and labeled","photo_required":false,"pts":5},{"id":"whse_s3_i4","label":"All stocks stored in proper storage","photo_required":false,"pts":5},{"id":"whse_s3_i5","label":"No material is placed directly on the floor","photo_required":false,"pts":5},{"id":"whse_s3_i6","label":"Chillers, refrigerators and freezer are clean and in good condition.","photo_required":false,"pts":5},{"id":"whse_s3_i7","label":"Floor - clean, dry, well maintained","photo_required":false,"pts":1},{"id":"whse_s3_i8","label":"Walls - clean, no shoe step marks, no stains, no scotch tape.","photo_required":false,"pts":1},{"id":"whse_s3_i9","label":"Ceiling is cleaned and No busted lights","photo_required":false,"pts":1},{"id":"whse_s3_i10","label":"Plastic curtain - clean, dry, stain-free","photo_required":false,"pts":1},{"id":"whse_s3_i11","label":"Electrical wire/plugs- safe and properly installed.","photo_required":false,"pts":1},{"id":"whse_s3_i12","label":"Instructional guides in proper places","photo_required":false,"pts":1},{"id":"whse_s3_i13","label":"Others","photo_required":false,"pts":1}]},{"id":"whse_s4","title":"D. MAIN STOCKROOM","items":[{"id":"whse_s4_i1","label":"Area is free from insects and rodent infestation","photo_required":false,"pts":5},{"id":"whse_s4_i2","label":"Area is free from physical hazard","photo_required":false,"pts":5},{"id":"whse_s4_i3","label":"Warehouse team are wearing prescribed uniform","photo_required":false,"pts":5},{"id":"whse_s4_i4","label":"Dispatcher''s table is clean and organized.","photo_required":false,"pts":5},{"id":"whse_s4_i5","label":"Only prepared stocks placed in staging area.","photo_required":false,"pts":5},{"id":"whse_s4_i6","label":"Accurate and complete inventory (random checking of stocks inventory)","photo_required":false,"pts":5},{"id":"whse_s4_i7","label":"Correct and monitored shelf life of stocks","photo_required":false,"pts":5},{"id":"whse_s4_i8","label":"Stocks are properly organized","photo_required":false,"pts":5},{"id":"whse_s4_i9","label":"All stocks stored in proper storage","photo_required":false,"pts":5},{"id":"whse_s4_i10","label":"Chemical stocks are separate from food stocks","photo_required":false,"pts":5},{"id":"whse_s4_i11","label":"No material is placed directly on floor","photo_required":false,"pts":5},{"id":"whse_s4_i12","label":"Stocks are arrange in FIFO method.","photo_required":false,"pts":5},{"id":"whse_s4_i13","label":"Matrix schedule followed","photo_required":false,"pts":5},{"id":"whse_s4_i14","label":"Racks, cabinets and shelves - clean, properly labeled, organized","photo_required":false,"pts":5},{"id":"whse_s4_i15","label":"Stairways and doorways are clear for a safe clearance","photo_required":false,"pts":5},{"id":"whse_s4_i16","label":"Aisles are clear and open for material transfers","photo_required":false,"pts":1},{"id":"whse_s4_i17","label":"Consistently practice \"clean as you go\" procedures","photo_required":false,"pts":1},{"id":"whse_s4_i18","label":"Floor - clean, dry, stain-free","photo_required":false,"pts":1},{"id":"whse_s4_i19","label":"Ceiling - clean, free from cobwebs","photo_required":false,"pts":1},{"id":"whse_s4_i20","label":"Walls - clean, no shoe step marks, no stains, no scotch tape.","photo_required":false,"pts":1},{"id":"whse_s4_i21","label":"Pallets - clean, good condition","photo_required":false,"pts":1},{"id":"whse_s4_i22","label":"Trolleys - clean, in good condition","photo_required":false,"pts":1},{"id":"whse_s4_i23","label":"Exhaust louver  should be well maintained, clean and in good condition","photo_required":false,"pts":1},{"id":"whse_s4_i24","label":"Industrial fan is clean and in good condition.","photo_required":false,"pts":1},{"id":"whse_s4_i25","label":"Electrical wire/plugs- safe and properly installed.","photo_required":false,"pts":1},{"id":"whse_s4_i26","label":"No busted lights","photo_required":false,"pts":1},{"id":"whse_s4_i27","label":"Garbage bin must be clean, with plastic liner, and with cover.","photo_required":false,"pts":1},{"id":"whse_s4_i28","label":"All fire extinguishers inspected, accessible and their locations clearly designed","photo_required":false,"pts":1},{"id":"whse_s4_i29","label":"Instructional guides in proper places","photo_required":false,"pts":1},{"id":"whse_s4_i30","label":"No personal belongings on area","photo_required":false,"pts":1},{"id":"whse_s4_i31","label":"Others","photo_required":false,"pts":1}]},{"id":"whse_s5","title":"E. DELIVERY VEHICLES - clean, in good running condition","items":[{"id":"whse_s5_i1","label":"UCD 426","photo_required":false,"pts":5},{"id":"whse_s5_i2","label":"WCT 769","photo_required":false,"pts":5},{"id":"whse_s5_i3","label":"XJG 481","photo_required":false,"pts":5},{"id":"whse_s5_i4","label":"WDG 497","photo_required":false,"pts":5},{"id":"whse_s5_i5","label":"WFX 175","photo_required":false,"pts":5},{"id":"whse_s5_i6","label":"ZBE 150","photo_required":false,"pts":5},{"id":"whse_s5_i7","label":"WHL 50","photo_required":false,"pts":5},{"id":"whse_s5_i8","label":"REF VAN","photo_required":false,"pts":5}]}]'::jsonb,
  true, 'others', false,
  92.5, true, false, true,
  false, false, '', '',
  (
    SELECT jsonb_agg(jsonb_build_object('brand_id', b.id, 'brand_name', b.brand_name, 'store_id', s.id, 'store_name', s.store_name))
    FROM public.stores s
    JOIN public.brands b ON b.id = s.brand_id
    WHERE s.store_name IN ('Mayon Warehouse', 'Consolacion Warehouse', 'CDO Warehouse')
  ),
  now(), now()
WHERE NOT EXISTS (
  SELECT 1 FROM public.audit_templates WHERE title = 'Warehouse Facility Audit Checklist'
);

